// UpsampleNearest3d kernel: nearest-neighbor 3D upsampling
// Uses AscendC::Gather to collect output elements from source rows based on
// precomputed w_src indices.
// Shared w_src index array is loaded once and reused across all output rows.

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class UpsampleNearest3dKernel {
public:
    __aicore__ inline UpsampleNearest3dKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR d_src, GM_ADDR h_src,
                                 GM_ADDR w_src, GM_ADDR output,
                                 int64_t N, int64_t C, int64_t iD, int64_t iH, int64_t iW,
                                 int64_t oD, int64_t oH, int64_t oW, int64_t rows,
                                 int64_t formerNum, int64_t formerLength,
                                 int64_t tailLength, int64_t dtypeSize);
    __aicore__ inline void Process();

private:
    __aicore__ inline void LoadWsrc();
    __aicore__ inline int64_t DecodeSourceOffset(int64_t rowIdx);
    __aicore__ inline void ProcessRow(int64_t rowIdx);

    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
    TBuf<TPosition::VECCALC> wSrcBuf;
    TBuf<TPosition::VECCALC> workBuf;

    GlobalTensor<T> inputGm;
    GlobalTensor<int32_t> dSrcGm;
    GlobalTensor<int32_t> hSrcGm;
    GlobalTensor<int32_t> wSrcGm;
    GlobalTensor<T> outputGm;

    int64_t N_, C_, iD_, iH_, iW_;
    int64_t oD_, oH_, oW_, rows_;
    int64_t startRow_, endRow_;
    int64_t alignedIW_, alignedOW_;
    int64_t dtypeSize_;
    int64_t iDHiW_;    // iD * iH * iW
    int64_t iHW_;      // iH * iW
    int64_t oHoW_;     // oH * oW
    int64_t cIdHiW_;   // C * iD * iH * iW
};

// =========================== Init ============================

template <typename T>
__aicore__ inline void UpsampleNearest3dKernel<T>::Init(
    GM_ADDR input, GM_ADDR d_src, GM_ADDR h_src, GM_ADDR w_src, GM_ADDR output,
    int64_t N, int64_t C, int64_t iD, int64_t iH, int64_t iW,
    int64_t oD, int64_t oH, int64_t oW, int64_t rows,
    int64_t formerNum, int64_t formerLength, int64_t tailLength, int64_t dtypeSize) {

    N_ = N; C_ = C; iD_ = iD; iH_ = iH; iW_ = iW;
    oD_ = oD; oH_ = oH; oW_ = oW; rows_ = rows;
    dtypeSize_ = dtypeSize;

    iDHiW_ = iD_ * iH_ * iW_;
    iHW_   = iH_ * iW_;
    oHoW_  = oH_ * oW_;
    cIdHiW_ = C_ * iDHiW_;

    // 32B-aligned row sizes
    constexpr int64_t UB_ALIGN = 32;
    int64_t alignElts = UB_ALIGN / static_cast<int64_t>(sizeof(T));
    if (alignElts < 1) alignElts = 1;
    alignedIW_ = ((iW_ + alignElts - 1) / alignElts) * alignElts;
    alignedOW_ = ((oW_ + alignElts - 1) / alignElts) * alignElts;

    // Set global tensors
    inputGm.SetGlobalBuffer((__gm__ T*)input);
    dSrcGm.SetGlobalBuffer((__gm__ int32_t*)d_src);
    hSrcGm.SetGlobalBuffer((__gm__ int32_t*)h_src);
    wSrcGm.SetGlobalBuffer((__gm__ int32_t*)w_src);
    outputGm.SetGlobalBuffer((__gm__ T*)output);

    // Determine which rows this core handles
    // Block-level tiling: former cores get formerLength elements, tail core gets tailLength
    int64_t blockIdx = GetBlockIdx();
    int64_t coreStartElem, coreEndElem;
    if (blockIdx < formerNum) {
        coreStartElem = blockIdx * formerLength;
        coreEndElem = coreStartElem + formerLength;
    } else {
        coreStartElem = formerNum * formerLength;
        coreEndElem = coreStartElem + tailLength;
    }
    int64_t totalOutputElems = rows_ * oW_;
    if (coreEndElem > totalOutputElems) coreEndElem = totalOutputElems;
    if (coreStartElem >= totalOutputElems) {
        startRow_ = rows_;
        endRow_ = rows_;
    } else {
        startRow_ = coreStartElem / oW_;
        endRow_ = (coreEndElem + oW_ - 1) / oW_;
        if (endRow_ > rows_) endRow_ = rows_;
    }

    // Allocate buffers
    // wSrcBuf: oW * sizeof(int32_t), 32B aligned
    int64_t wSrcAlignedBytes = ((oW_ * (int64_t)sizeof(int32_t) + UB_ALIGN - 1) / UB_ALIGN) * UB_ALIGN;
    pipe.InitBuffer(wSrcBuf, wSrcAlignedBytes);

    // workBuf: for half/bf16 Cast (float32 work buffer for one row)
    // max(iW_, oW_) * sizeof(float), 32B aligned
    int64_t maxElems = (iW_ > oW_) ? iW_ : oW_;
    int64_t workBufBytes = ((maxElems * (int64_t)sizeof(float) + UB_ALIGN - 1) / UB_ALIGN) * UB_ALIGN;
    pipe.InitBuffer(workBuf, workBufBytes);

    // inQueue: source row buffer, alignedIW_ elements × BUFFER_NUM
    pipe.InitBuffer(inQueue, BUFFER_NUM, alignedIW_ * sizeof(T));

    // outQueue: output row buffer, alignedOW_ elements × BUFFER_NUM
    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedOW_ * sizeof(T));
}

// =========================== LoadWsrc ============================

template <typename T>
__aicore__ inline void UpsampleNearest3dKernel<T>::LoadWsrc() {
    LocalTensor<int32_t> wSrcLocal = wSrcBuf.Get<int32_t>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(oW_ * sizeof(int32_t));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;

    DataCopyPadExtParams<int32_t> padParams;
    padParams.isPad = false;

    DataCopyPad(wSrcLocal, wSrcGm, copyParams, padParams);
    PipeBarrier<PIPE_ALL>();

    // Convert element indices to byte offsets via Muls
    // For float32 path: multiply by sizeof(float)=4
    // For half/bf16: also multiply by 4 because we'll Cast to float32 before Gather
    const int32_t byteMultiplier = static_cast<int32_t>(sizeof(float));
    Muls(wSrcLocal, wSrcLocal, byteMultiplier, oW_);
    PipeBarrier<PIPE_ALL>();
}

// =========================== DecodeSourceOffset ============================

template <typename T>
__aicore__ inline int64_t UpsampleNearest3dKernel<T>::DecodeSourceOffset(int64_t rowIdx) {
    // Decode (n, c, d_o, h_o) from flat row index
    // row = n * C * oD * oH + c * oD * oH + d_o * oH + h_o
    int64_t n   = rowIdx / (C_ * oD_ * oHoW_ / oH_);  // n = rowIdx / (C * oD * oH)
    int64_t rem = rowIdx % (C_ * oD_ * oHoW_ / oH_);
    // Wait, let me recalculate.
    // Actually: rowIdx = n * (C * oD * oH) + c * (oD * oH) + d_o * oH + h_o
    // rows_ = N_ * C_ * oD_ * oH
    int64_t coDoH = C_ * oD_ * oH_;
    n = rowIdx / coDoH;
    rem = rowIdx % coDoH;
    int64_t c   = rem / (oD_ * oH_);
    rem = rem % (oD_ * oH_);
    int64_t d_o = rem / oH_;
    int64_t h_o = rem % oH_;

    // Read d_src[d_o] and h_src[h_o] from GM
    int32_t dSrcVal = dSrcGm.GetValue(d_o);
    int32_t hSrcVal = hSrcGm.GetValue(h_o);

    // Source offset for (n, c, d_src[d_o], h_src[h_o], 0)
    return n * cIdHiW_ + c * iDHiW_ + (int64_t)dSrcVal * iHW_ + (int64_t)hSrcVal * iW_;
}

// =========================== ProcessRow ============================

template <typename T>
__aicore__ inline void UpsampleNearest3dKernel<T>::ProcessRow(int64_t rowIdx) {
    int64_t srcOffset = DecodeSourceOffset(rowIdx);
    int64_t dstOffset = rowIdx * oW_;

    LocalTensor<int32_t> wSrcLocal = wSrcBuf.Get<int32_t>();
    LocalTensor<uint32_t> idxLocal = wSrcLocal.ReinterpretCast<uint32_t>();

    if constexpr (sizeof(T) == sizeof(float)) {
        // FP32: direct Gather
        LocalTensor<float> srcLocal = inQueue.AllocTensor<float>();
        LocalTensor<float> outLocal = outQueue.AllocTensor<float>();

        // CopyIn: load source row
        DataCopyExtParams copyInParams;
        copyInParams.blockCount = 1;
        copyInParams.blockLen = static_cast<uint32_t>(iW_ * sizeof(float));
        copyInParams.srcStride = 0;
        copyInParams.dstStride = 0;
        DataCopyPadExtParams<float> padInParams;
        padInParams.isPad = false;
        DataCopyPad(srcLocal, inputGm[srcOffset], copyInParams, padInParams);
        PipeBarrier<PIPE_ALL>();
        inQueue.EnQue<float>(srcLocal);

        // Gather
        LocalTensor<float> srcIn = inQueue.DeQue<float>();
        Gather(outLocal, srcIn, idxLocal, (uint32_t)0, (uint32_t)oW_);
        PipeBarrier<PIPE_ALL>();
        outQueue.EnQue<float>(outLocal);
        inQueue.FreeTensor(srcIn);

        // CopyOut
        LocalTensor<float> outReady = outQueue.DeQue<float>();
        DataCopyExtParams copyOutParams;
        copyOutParams.blockCount = 1;
        copyOutParams.blockLen = static_cast<uint32_t>(oW_ * sizeof(float));
        copyOutParams.srcStride = 0;
        copyOutParams.dstStride = 0;
        DataCopyPad(outputGm[dstOffset], outReady, copyOutParams);
        PipeBarrier<PIPE_ALL>();
        outQueue.FreeTensor(outReady);

    } else {
        // FP16/BF16: Cast to float32 → Gather → Cast back
        LocalTensor<float> workF32 = workBuf.Get<float>();

        LocalTensor<T> srcLocal = inQueue.AllocTensor<T>();
        LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        // CopyIn: load source row in original dtype
        DataCopyExtParams copyInParams;
        copyInParams.blockCount = 1;
        copyInParams.blockLen = static_cast<uint32_t>(iW_ * sizeof(T));
        copyInParams.srcStride = 0;
        copyInParams.dstStride = 0;
        DataCopyPadExtParams<T> padInParams;
        padInParams.isPad = false;
        DataCopyPad(srcLocal, inputGm[srcOffset], copyInParams, padInParams);
        PipeBarrier<PIPE_ALL>();
        inQueue.EnQue<T>(srcLocal);

        // Cast source to float32
        LocalTensor<T> srcIn = inQueue.DeQue<T>();
        Cast(workF32, srcIn, RoundMode::CAST_NONE, iW_);
        PipeBarrier<PIPE_ALL>();
        inQueue.FreeTensor(srcIn);

        // Gather from float32 source
        Gather(outLocal.ReinterpretCast<float>(), workF32, idxLocal,
               (uint32_t)0, (uint32_t)oW_);
        PipeBarrier<PIPE_ALL>();

        // Cast output back to T
        Cast(outLocal, outLocal.ReinterpretCast<float>(), RoundMode::CAST_ROUND, oW_);
        PipeBarrier<PIPE_ALL>();
        outQueue.EnQue<T>(outLocal);

        // CopyOut
        LocalTensor<T> outReady = outQueue.DeQue<T>();
        DataCopyExtParams copyOutParams;
        copyOutParams.blockCount = 1;
        copyOutParams.blockLen = static_cast<uint32_t>(oW_ * sizeof(T));
        copyOutParams.srcStride = 0;
        copyOutParams.dstStride = 0;
        DataCopyPad(outputGm[dstOffset], outReady, copyOutParams);
        PipeBarrier<PIPE_ALL>();
        outQueue.FreeTensor(outReady);
    }
}

// =========================== Process ============================

template <typename T>
__aicore__ inline void UpsampleNearest3dKernel<T>::Process() {
    if (startRow_ >= endRow_) return;

    // Load w_src index array once (shared across all rows)
    LoadWsrc();

    // Process each assigned row
    for (int64_t r = startRow_; r < endRow_; r++) {
        ProcessRow(r);
    }
}

// =========================== Kernel Entry ============================

extern "C" __global__ __aicore__ void upsample_nearest3d(
    GM_ADDR input, GM_ADDR d_src, GM_ADDR h_src, GM_ADDR w_src, GM_ADDR output,
    int64_t N, int64_t C, int64_t iD, int64_t iH, int64_t iW,
    int64_t oD, int64_t oH, int64_t oW, int64_t rows,
    int64_t formerNum, int64_t formerLength, int64_t tailLength, int64_t dtypeSize) {

    if (dtypeSize == 4) {
        UpsampleNearest3dKernel<float> op;
        op.Init(input, d_src, h_src, w_src, output,
                N, C, iD, iH, iW, oD, oH, oW, rows,
                formerNum, formerLength, tailLength, dtypeSize);
        op.Process();
    } else if (dtypeSize == 2) {
        // FP16 and BF16 both use half path (both are 2 bytes)
        UpsampleNearest3dKernel<half> op;
        op.Init(input, d_src, h_src, w_src, output,
                N, C, iD, iH, iW, oD, oH, oW, rows,
                formerNum, formerLength, tailLength, dtypeSize);
        op.Process();
    }
}
