// UpsampleNearest3d host-side implementation.
// Precomputes d_src, h_src, w_src index arrays, computes tiling,
// and launches the AscendC kernel.

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_upsample_nearest3d.h"
#include <cmath>

namespace ascend_kernel {

at::Tensor upsample_nearest3d(
    const at::Tensor &x,
    at::IntArrayRef output_size,
    double scale_d,
    double scale_h,
    double scale_w) {

    // ---- Input validation ----
    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
                "upsample_nearest3d: x must be on NPU device");
    TORCH_CHECK(x.dim() == 5,
                "upsample_nearest3d: x must be 5D (N,C,D,H,W), got ", x.dim(), "D");
    TORCH_CHECK(output_size.size() == 3,
                "upsample_nearest3d: output_size must have 3 elements [oD, oH, oW]");

    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "upsample_nearest3d: only float32, float16, bfloat16 supported");

    // ---- Dimensions ----
    int64_t N = x.size(0), C = x.size(1);
    int64_t iD = x.size(2), iH = x.size(3), iW = x.size(4);
    int64_t oD = output_size[0], oH = output_size[1], oW = output_size[2];

    // ---- Contiguous ----
    auto xContiguous = x.contiguous();

    // ---- Scale computation ----
    float s_d_f = static_cast<float>(scale_d);
    float s_h_f = static_cast<float>(scale_h);
    float s_w_f = static_cast<float>(scale_w);

    if (s_d_f <= 0.0f) s_d_f = static_cast<float>(iD) / static_cast<float>(oD);
    if (s_h_f <= 0.0f) s_h_f = static_cast<float>(iH) / static_cast<float>(oH);
    if (s_w_f <= 0.0f) s_w_f = static_cast<float>(iW) / static_cast<float>(oW);

    // ---- Precompute index arrays on CPU ----
    // d_src[oD]: d_src[d_o] = clamp(floor(d_o * s_d), 0, iD-1)
    auto dSrcCpu = at::empty({oD}, at::TensorOptions().dtype(at::kInt).device(at::kCPU));
    auto hSrcCpu = at::empty({oH}, at::TensorOptions().dtype(at::kInt).device(at::kCPU));
    auto wSrcCpu = at::empty({oW}, at::TensorOptions().dtype(at::kInt).device(at::kCPU));

    int32_t *dSrcPtr = dSrcCpu.data_ptr<int32_t>();
    int32_t *hSrcPtr = hSrcCpu.data_ptr<int32_t>();
    int32_t *wSrcPtr = wSrcCpu.data_ptr<int32_t>();

    float iDf = static_cast<float>(iD);
    float iHf = static_cast<float>(iH);
    float iWf = static_cast<float>(iW);

    for (int64_t d = 0; d < oD; d++) {
        float val = std::floor(static_cast<float>(d) * s_d_f);
        dSrcPtr[d] = static_cast<int32_t>(val < 0.0f ? 0 : (val > iDf - 1.0f ? iDf - 1.0f : val));
    }
    for (int64_t h = 0; h < oH; h++) {
        float val = std::floor(static_cast<float>(h) * s_h_f);
        hSrcPtr[h] = static_cast<int32_t>(val < 0.0f ? 0 : (val > iHf - 1.0f ? iHf - 1.0f : val));
    }
    for (int64_t w = 0; w < oW; w++) {
        float val = std::floor(static_cast<float>(w) * s_w_f);
        wSrcPtr[w] = static_cast<int32_t>(val < 0.0f ? 0 : (val > iWf - 1.0f ? iWf - 1.0f : val));
    }

    // Copy index arrays to NPU
    auto dSrcNpu = TorchNpuHelper::CopyTensorHostToDevice(dSrcCpu);
    auto hSrcNpu = TorchNpuHelper::CopyTensorHostToDevice(hSrcCpu);
    auto wSrcNpu = TorchNpuHelper::CopyTensorHostToDevice(wSrcCpu);

    // ---- Output tensor ----
    auto outputOpts = xContiguous.options();
    auto output = at::empty({N, C, oD, oH, oW}, outputOpts);

    int64_t rows = N * C * oD * oH;
    int64_t totalLength = rows * oW;
    int64_t dtypeSize = static_cast<int64_t>(xContiguous.element_size());

    if (totalLength == 0) return output;

    // ---- Block-level tiling ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());

    // Cache line alignment (512B)
    constexpr int64_t CACHE_LINE_BYTES = 512;
    int64_t alignElements = CACHE_LINE_BYTES / dtypeSize;
    if (alignElements < 1) alignElements = 1;

    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElements - 1) / alignElements) * alignElements;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    if (formerNum < 1) formerNum = 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

